#include "Tokens.h"
#include <cctype>
#include <stdexcept>

namespace calc {

int precedence(char op) {
    switch (op) {
        case '+':
        case '-':
            return 1;
        case '*':
        case '/':
            return 2;
        default:
            throw std::domain_error("Invalid operator for precedence");
    }
}

bool isLeftAssociative(char op) {
    return op == '+' || op == '-' || op == '*' || op == '/';
}

bool isOperatorChar(char c) {
    return c == '+' || c == '-' || c == '*' || c == '/';
}

} // namespace calc
