#ifndef CALC_TOKENS_H
#define CALC_TOKENS_H

#include <cstdint>
#include <string>

namespace calc {

enum class TokenType : std::uint8_t {
    NUMBER,
    OPERATOR,
    LEFT_PAREN,
    RIGHT_PAREN
};

struct Token {
    TokenType type;
    double numberValue;  // valid only if type == NUMBER
    char op;             // valid only if type == OPERATOR
    std::size_t position; // zero-based index of token in original expression

    Token(TokenType t, std::size_t pos) : type(t), numberValue(0.0), op('\0'), position(pos) {}
    Token(TokenType t, double val, std::size_t pos) : type(t), numberValue(val), op('\0'), position(pos) {}
    Token(TokenType t, char o, std::size_t pos) : type(t), numberValue(0.0), op(o), position(pos) {}
};

// Helper functions for operator precedence and associativity
int precedence(char op);
bool isLeftAssociative(char op);
bool isOperatorChar(char c);

} // namespace calc

#endif // CALC_TOKENS_H
