#ifndef CALCULATOR_TOKENS_H
#define CALCULATOR_TOKENS_H

#include <cstddef>
#include <string>

namespace calc {

enum class TokenType {
    NUMBER,
    OPERATOR,
    LEFT_PAREN,
    RIGHT_PAREN
};

struct Token {
    TokenType type;
    double numberValue;  // Valid only if type == NUMBER
    char op;             // Valid only if type == OPERATOR
    size_t position;     // Source position for error reporting
};

// Helper functions for operator precedence and associativity
int precedence(char op);
bool isLeftAssociative(char op);
bool isOperatorChar(char ch);

} // namespace calc

#endif // CALCULATOR_TOKENS_H
