#include "Tokens.h"
#include <cctype>
#include <stdexcept>

namespace calc {

int precedence(char op) {
    switch (op) {
        case '+':
        case '-':
            return 1;
        case '*':
        case '/':
            return 2;
        default:
            return -1; // Not an operator
    }
}

bool isLeftAssociative(char op) {
    return op == '+' || op == '-' ||

