/**
 * Enum representing the different types of tokens that can be produced by the tokenizer.
 */
public enum TokenType {
    /**
     * Represents a numeric literal token.
     */
    NUMBER,

    /**
     * Represents the plus operator token.
     */
    PLUS,

    /**
     * Represents the minus operator token.
     */
    MINUS,

    /**
     * Represents the multiplication operator token.
     */
    STAR,

    /**
     * Represents the division operator token.
     */
    SLASH,

    /**
     * Represents the left parenthesis token.
     */
    LPAREN,

    /**
     * Represents the right parenthesis token.
     */
    RPAREN,

    /**
     * Represents the end-of-file token.
     */
    EOF
}
